const item = $input.item;
const body = item.json.body || {};
const headers = item.json.headers || {};

// ===== NUEVO 1: catálogo de productos (forma × versión) =====
const PRODUCT_CATALOG = {
  college: {
    current: { title: "MEDLIFE Chapter Kit 26-27",             productId: "ID_PRODUCTO_COLLEGE_2026", variantId: "ID_VARIANTE_COLLEGE_2026" },
    legacy:  { title: "MEDLIFE Kit for College Chapters 2025", productId: "9796557898008",            variantId: "50401230815512" }
  },
  hs: {
    current: { title: "MEDLIFE Kit for High school Chapters 2026", productId: "10249804874008", variantId: "51989351498008" },
    legacy:  { title: "MEDLIFE Kit for High school Chapters 2025", productId: "9796559962392",  variantId: "50401238188312" }
  }
};

// ===== NUEVO 2: ¿hay stock del kit 2026? (por forma) =====
const STOCK_2026 = {
  college: false,
  hs: true
};

// ===== NUEVO 3: forma de origen según el form_id que envía HubSpot =====
const FORM_MAP = {
  "de306230-7676-4775-9bd5-179094f8a770": "college",
  "f2f5112e-9426-47e8-8abd-04315230862a": "hs"
};
const rawFormId = String(body.hs_form_id ?? '').trim().toLowerCase();
const formType = FORM_MAP[rawFormId] || null;

// --- HubSpot -> columnas Shopify ---
const fullName = String(body.promo_materials_name ?? '').trim();
const nameParts = fullName.split(/\s+/);
const firstName = nameParts.shift() || '';
const lastName = nameParts.join(' ') || '';

const data = {
  Name: firstName,
  'Last Name': lastName,
  Email: String(body.delivery_contact_email ?? '').trim(),
  Phone: String(body.delivery_contact_phone ?? '').trim(),
  Company: String(body.high_school_or_university_name ?? '').trim(),
  'Street Address': String(body.delivery_address_line_1 ?? '').trim(),
  City: String(body.delivery_address_city ?? '').trim(),
  'Province/State': String(body.delivery_address_state_region ?? '').trim(),
  Country: String(body.delivery_address_country ?? '').trim(),
  ZIP: String(body.delivery_address_zip_code ?? '').trim()
};

// --- 1. Normalizar nombre de país (variantes comunes) ---
// >>> CAMBIO: Hong Kong y South Korea agregados (son países propios en Shopify, NO China)
const countryAliases = {
  'usa': 'United States', 'us': 'United States', 'u.s.a.': 'United States',
  'united states of america': 'United States', 'estados unidos': 'United States',
  'puerto rico': 'United States',
  'canada': 'Canada', 'canadá': 'Canada',
  'china': 'China', 'prc': 'China', "people's republic of china": 'China',
  'uk': 'United Kingdom', 'u.k.': 'United Kingdom', 'great britain': 'United Kingdom',
  'hong kong': 'Hong Kong', 'hk': 'Hong Kong', 'hong kong sar': 'Hong Kong',
  'south korea': 'South Korea', 'korea del sur': 'South Korea', 'corea del sur': 'South Korea',
  'republic of korea': 'South Korea', 'kr': 'South Korea', 'korea, south': 'South Korea'
};
let country = String(data.Country ?? '').trim();
const countryKey = country.toLowerCase();
if (countryAliases[countryKey]) {
  country = countryAliases[countryKey];
}

// --- 2. Mapeo de provincia/estado SEGÚN el país ---
const usStates = {
  AL: "Alabama", AK: "Alaska", AZ: "Arizona", AR: "Arkansas", CA: "California",
  CO: "Colorado", CT: "Connecticut", DE: "Delaware", FL: "Florida", GA: "Georgia",
  HI: "Hawaii", ID: "Idaho", IL: "Illinois", IN: "Indiana", IA: "Iowa",
  KS: "Kansas", KY: "Kentucky", LA: "Louisiana", ME: "Maine", MD: "Maryland",
  MA: "Massachusetts", MASSACHUSETTS: "Massachusetts", MI: "Michigan", MN: "Minnesota", MS: "Mississippi", MO: "Missouri",
  MT: "Montana", NE: "Nebraska", NV: "Nevada", NH: "New Hampshire", NJ: "New Jersey",
  NM: "New Mexico", NY: "New York", NC: "North Carolina", ND: "North Dakota", OH: "Ohio",
  OK: "Oklahoma", OR: "Oregon", PA: "Pennsylvania", RI: "Rhode Island", SC: "South Carolina",
  SD: "South Dakota", TN: "Tennessee", TX: "Texas", UT: "Utah", VT: "Vermont",
  VA: "Virginia", WA: "Washington", WV: "West Virginia", WI: "Wisconsin", WY: "Wyoming",
  DC: "District of Columbia", PR: "Puerto Rico"
};
const caProvinces = {
  AB: "Alberta", BC: "British Columbia", MB: "Manitoba", NB: "New Brunswick",
  NL: "Newfoundland and Labrador", NS: "Nova Scotia", NT: "Northwest Territories",
  NU: "Nunavut", ON: "Ontario", PE: "Prince Edward Island", QC: "Quebec",
  SK: "Saskatchewan", YT: "Yukon"
};
let province = String(data['Province/State'] ?? '').trim();
const provinceUpper = province.toUpperCase();
if (country === 'United States' && usStates[provinceUpper]) {
  province = usStates[provinceUpper];
} else if (country === 'Canada' && caProvinces[provinceUpper]) {
  province = caProvinces[provinceUpper];
}
if (provinceUpper === 'PR' || province.toLowerCase() === 'puerto rico') {
  country = 'United States';
  province = 'Puerto Rico';
}

// --- 3. Normalizar ZIP ---
// >>> CAMBIO: limpia caracteres no numéricos y solo recupera ceros a la izquierda
//     cuando es seguro (número corto SIN cero inicial, ej. 653 -> 00653).
//     Un valor que ya trae cero inicial y viene corto (ej. "0096-") es incompleto
//     -> se deja tal cual para que la validación de abajo lo mande a error.
let zip = String(data.ZIP ?? '').trim();
if (country === 'United States') {
  const raw = zip;
  const digits = zip.replace(/\D/g, ''); // quita guiones, espacios, letras
  if (digits.length >= 9) {
    zip = digits.slice(0, 5) + '-' + digits.slice(5, 9); // 009601234 -> 00960-1234
  } else if (digits.length === 5) {
    zip = digits;
  } else if (digits.length < 5 && !raw.startsWith('0')) {
    zip = digits.padStart(5, '0'); // 653 -> 00653 (pérdida de ceros a la izquierda)
  } else {
    zip = digits; // incompleto/typo -> lo atrapa la validación
  }
}

// --- 4. Días hasta la feria + versión de kit ---
const fairDateRaw = body.activities_fair_date;
const fairDate = fairDateRaw ? new Date(fairDateRaw) : null;
const today = new Date();
const msPerDay = 1000 * 60 * 60 * 24;
let daysUntilFair = null;
let useLegacyKit = false; // true = kit 2025 (feria <= 15 días)
if (fairDate && !isNaN(fairDate.getTime())) {
  daysUntilFair = Math.ceil((fairDate - today) / msPerDay);
  useLegacyKit = daysUntilFair <= 15;
}
const kitVersion = useLegacyKit ? 'legacy' : 'current';

// ===== NUEVO 4: resolver el producto (forma × versión) =====
let product = null;
if (formType && PRODUCT_CATALOG[formType]) {
  product = PRODUCT_CATALOG[formType][kitVersion] || null;
}

// --- 5. Validación de campos obligatorios ---
const requiredFields = ['Name', 'Last Name', 'Email', 'Street Address', 'City', 'ZIP', 'Country'];
const missing = requiredFields.filter(f => {
  const value = data[f];
  return value === undefined || value === null || String(value).trim() === '';
});

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(data.Email ?? '').trim());
if (!emailValid) missing.push('Email (formato inválido)');

// >>> CAMBIO: Hong Kong y South Korea agregados a la lista de países permitidos
const knownCountries = ['United States', 'Canada', 'China', 'United Kingdom', 'Hong Kong', 'South Korea'];
if (!knownCountries.includes(country)) {
  missing.push(`País no reconocido: "${data.Country}"`);
}

// >>> CAMBIO: validar formato de ZIP solo para US/PR (5 dígitos, o 5+4)
if (country === 'United States') {
  if (!/^\d{5}(-\d{4})?$/.test(zip)) {
    missing.push(`ZIP inválido para US/PR: "${data.ZIP}"`);
  }
}

// ===== NUEVO 5: validar forma y producto =====
if (!formType) missing.push(`Forma no reconocida (hs_form_id): "${body.hs_form_id ?? '(vacío)'}"`);
if (formType && !product) missing.push(`Sin producto configurado para ${formType}/${kitVersion}`);

const isValid = missing.length === 0;

// ===== NUEVO 6: decisión de ruta =====
let route;
if (!isValid) {
  route = 'error';
} else if (kitVersion === 'legacy') {
  route = 'ship_now';
} else if (STOCK_2026[formType]) {
  route = 'ship_now';
} else {
  route = 'hold_2026';
}

// --- 6. Salida ---
item.json = {
  ...data,
  Country: country,
  'Province/State': province,
  ZIP: zip,
  'Item Title':  product ? product.title    : '',
  'Product ID':  product ? product.productId : '',
  'Variant ID':  product ? product.variantId : '',
  Quantity: 1,
  formType,
  kitVersion,
  useLegacyKit,
  daysUntilFair,
  activities_fair_date: fairDateRaw ?? '',
  fair_date_readable: (fairDate && !isNaN(fairDate.getTime())) ? fairDate.toISOString().slice(0, 10) : '',
  pending_id: String(headers['x-hubspot-correlation-id'] ?? `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`),
  status: 'pending',
  created_at: today.toISOString(),
  route,
  isValid,
  validationErrors: missing.length ? `Faltan o son inválidos: ${missing.join(', ')}` : ''
};

return item;

